    [['otitle', 'title'], ['otour', 'tour'], ['oev', 'eventId'], ['omc', 'mc'], ['otb', 'tb'], ['orank', 'rank'], ['oentry', 'entry'], ['opot', 'pot'], ['otake', 'take'], ['ofmt', 'fmt'], ['onet', 'net'], ['opct', 'pct'], ['ocount', 'count'], ['odrives', 'drives'], ['oteams', 'teams'], ['opair', 'pair'], ['ohkind', 'hkind'], ['ohtype', 'htype'], ['ohamt', 'hamt'], ['oskamt', 'skamt'], ['octp', 'ctp'], ['old', 'ld'], ['omyh', 'myHcp'], ['odate', 'date'], ['otee', 'tee'], ['osplit', 'split'], ['oskend', 'skend'], ['oskwd', 'skwd'], ['otsize', 'tsize'], ['odpen', 'dpen'], ['opress', 'press'], ['ohpct', 'hpct'], ['oflights', 'flights'], ['opayby', 'payBy']].forEach(([id, k]) => { const x = v(id); if (x !== null) d[k] = x; });
